<?php
declare(strict_types=1);
session_start();
$dbFile = __DIR__ . '/data/tpy.sqlite';
if (!is_file($dbFile)) { http_response_code(503); exit('Сначала выполните: python setup.py'); }
$db = new PDO('sqlite:' . $dbFile);
$db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
function e($value): string { return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function money(int $value): string { return number_format($value, 0, ',', ' ') . ' ₽'; }
function userId(): int { return (int)($_SESSION['uid'] ?? 0); }
function csrf(): string { return $_SESSION['csrf'] ??= bin2hex(random_bytes(24)); }
function go(string $url = 'index.php'): never { header('Location: ' . $url); exit; }
function flash(string $text): void { $_SESSION['flash'] = $text; }
function requireUser(): void { if (!userId()) { flash('Сначала войдите в аккаунт.'); go('?page=login'); } }
function query(PDO $db, string $sql, array $params=[]): PDOStatement { $s=$db->prepare($sql); $s->execute($params); return $s; }
if ($_SERVER['REQUEST_METHOD']==='POST') {
 if (!hash_equals(csrf(), (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Неверный защитный токен'); }
 $action=$_POST['action'] ?? '';
 try {
  if ($action==='register') {
   $name=trim((string)($_POST['name'] ?? '')); $email=mb_strtolower(trim((string)($_POST['email'] ?? ''))); $password=(string)($_POST['password'] ?? '');
   if (mb_strlen($name)<2 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($password)<8) throw new RuntimeException('Укажите имя, корректный email и пароль от 8 символов.');
   query($db,'INSERT INTO users (name,email,password_hash) VALUES (?,?,?)',[$name,$email,password_hash($password,PASSWORD_DEFAULT)]);
   session_regenerate_id(true); $_SESSION['uid']=(int)$db->lastInsertId(); flash('Добро пожаловать в TPY!'); go('?page=account');
  }
  if ($action==='login') {
   $u=query($db,'SELECT * FROM users WHERE email=?',[mb_strtolower(trim((string)($_POST['email'] ?? '')))] )->fetch();
   if (!$u || !password_verify((string)($_POST['password'] ?? ''),$u['password_hash'])) throw new RuntimeException('Неверная почта или пароль.');
   session_regenerate_id(true); $_SESSION['uid']=(int)$u['id']; go('?page=account');
  }
  if ($action==='logout') { $_SESSION=[]; session_regenerate_id(true); go(); }
  requireUser();
  if ($action==='add') {
   $id=(int)($_POST['product_id'] ?? 0);
   if (!query($db,'SELECT id FROM products WHERE id=?',[$id])->fetch()) throw new RuntimeException('Товар не найден.');
   query($db,'INSERT INTO cart_items (user_id,product_id,quantity) VALUES (?,?,1) ON CONFLICT(user_id,product_id) DO UPDATE SET quantity=MIN(quantity+1,99)',[userId(),$id]);
   flash('Товар добавлен в корзину.'); go('?page=cart');
  }
  if ($action==='remove') { query($db,'DELETE FROM cart_items WHERE user_id=? AND product_id=?',[userId(),(int)($_POST['product_id'] ?? 0)]); go('?page=cart'); }
  if ($action==='review') {
   $rating=(int)($_POST['rating'] ?? 0); $body=trim((string)($_POST['body'] ?? '')); $pid=(int)($_POST['product_id'] ?? 0);
   if ($rating<1 || $rating>5 || mb_strlen($body)<5 || mb_strlen($body)>1000 || !query($db,'SELECT id FROM products WHERE id=?',[$pid])->fetch()) throw new RuntimeException('Выберите товар, оценку и напишите отзыв от 5 до 1000 символов.');
   query($db,'INSERT INTO reviews (user_id,product_id,rating,body) VALUES (?,?,?,?)',[userId(),$pid,$rating,$body]); flash('Спасибо за отзыв!'); go('?page=reviews');
  }
  if ($action==='card') {
   $label=trim((string)($_POST['label'] ?? '')); $last=trim((string)($_POST['last_four'] ?? ''));
   if (mb_strlen($label)<2 || mb_strlen($label)>30 || !preg_match('/^[0-9]{4}$/',$last)) throw new RuntimeException('Введите название и ровно 4 последние цифры карты.');
   query($db,'INSERT INTO saved_cards (user_id,label,last_four) VALUES (?,?,?)',[userId(),$label,$last]); flash('Демонстрационная карта добавлена.'); go('?page=account');
  }
  if ($action==='delete_card') { query($db,'DELETE FROM saved_cards WHERE id=? AND user_id=?',[(int)($_POST['card_id'] ?? 0),userId()]); go('?page=account'); }
  if ($action==='checkout') {
   $db->exec('BEGIN IMMEDIATE');
   $items=query($db,'SELECT p.*, c.quantity FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=?',[userId()])->fetchAll();
   if (!$items) throw new RuntimeException('Корзина пуста.');
   $total=0; foreach($items as $item) $total+=(int)$item['price']*(int)$item['quantity'];
   query($db,'INSERT INTO orders (user_id,total) VALUES (?,?)',[userId(),$total]); $oid=(int)$db->lastInsertId();
   foreach($items as $item) query($db,'INSERT INTO order_items (order_id,product_id,name,price,quantity) VALUES (?,?,?,?,?)',[$oid,$item['id'],$item['name'],$item['price'],$item['quantity']]);
   query($db,'DELETE FROM cart_items WHERE user_id=?',[userId()]); $db->commit(); flash('Тестовый заказ №'.$oid.' оформлен. Деньги не списаны.'); go('?page=orders');
  }
 } catch (Throwable $ex) { if ($db->inTransaction()) $db->rollBack(); flash($ex instanceof PDOException ? 'Не удалось выполнить действие. Проверьте данные (возможно, email уже зарегистрирован).' : $ex->getMessage()); go('?page='.urlencode((string)($_POST['return'] ?? 'home'))); }
}
$page=(string)($_GET['page'] ?? 'home'); $category=(string)($_GET['category'] ?? 'all');
$categories=['all'=>'Все ароматы','women'=>'Женские','men'=>'Мужские','unisex'=>'Унисекс','gift'=>'Сертификаты'];
if (!isset($categories[$category])) $category='all';
$products=query($db,'SELECT * FROM products '.($category==='all'?'':'WHERE category=?').' ORDER BY id',$category==='all'?[]:[$category])->fetchAll();
$cartCount=userId() ? (int)query($db,'SELECT COALESCE(SUM(quantity),0) FROM cart_items WHERE user_id=?',[userId()])->fetchColumn() : 0;
function formStart(string $action,string $return='home'): void { echo '<form method="post"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="return" value="'.e($return).'">'; }
function productCard(array $p): void { ?>
 <article class="product"><a href="?page=product&id=<?= (int)$p['id'] ?>"><div class="photo"><img loading="lazy" src="assets/images/<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"></div></a><div class="product-info"><span class="eyebrow"><?= e(['women'=>'ДЛЯ НЕЁ','men'=>'ДЛЯ НЕГО','unisex'=>'УНИСЕКС','gift'=>'ПОДАРОК'][$p['category']]) ?></span><h3><a href="?page=product&id=<?= (int)$p['id'] ?>"><?= e($p['name']) ?></a></h3><p><?= e($p['notes']) ?></p><div class="buy"><strong><?= money((int)$p['price']) ?></strong><?php formStart('add','catalog'); ?><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><button aria-label="Добавить в корзину" title="Добавить в корзину" class="add">＋</button></form></div></div></article>
<?php } ?>
